import { ApiError } from "./http.ts";
// Optional scheduler credential, never generated by this application. It is
// disabled unless an approved secret is explicitly configured server-side.
export async function authorizedJob(
  provided: string | null,
  configured: string | undefined,
): Promise<boolean> {
  if (provided === null) return false;
  if (!configured || !(/^[A-Za-z0-9_-]{43,256}$/).test(configured) || provided.length > 256) {
    throw new ApiError(403, "job_authorization_denied");
  }
  const encoder = new TextEncoder();
  const [a, b] = await Promise.all(
    [configured, provided].map((v) => crypto.subtle.digest("SHA-256", encoder.encode(v))),
  );
  const x = new Uint8Array(a), y = new Uint8Array(b);
  let different = 0;
  for (let i = 0; i < x.length; i++) different |= x[i] ^ y[i];
  if (different !== 0) throw new ApiError(403, "job_authorization_denied");
  return true;
}
